file.content:
{
  "source_url": "https://github.com/ethereum/execution-specs/blob/forks/amsterdam/src/ethereum/forks/osaka/state.py",
  "title": "Osaka Execution Spec -- State",
  "category": "execution-spec",
  "type": "Specification (Python)",
  "layer": "execution",
  "sub_graphs": [
    {
      "id": "SG-STATE-DATA-STRUCTURES",
      "name": "State Data Structures",
      "description": "Core data structures that hold all information preserved between transactions. The State contains a main account trie and per-contract storage tries. TransientStorage holds data preserved only within a single transaction across message calls.",
      "invariants": [
        {
          "id": "INV-STATE-001",
          "text": "There is a distinction between an account that does not exist (None) and EMPTY_ACCOUNT. A non-existent account maps to None in the trie, while EMPTY_ACCOUNT is a valid Account object with zero values."
        },
        {
          "id": "INV-STATE-002",
          "text": "The main trie is a secured trie (hashed keys) with a default value of None for non-existent accounts."
        },
        {
          "id": "INV-STATE-003",
          "text": "Each storage trie is a secured trie with a default value of U256(0)."
        },
        {
          "id": "INV-STATE-004",
          "text": "TransientStorage is scoped to a single transaction and is not preserved across transactions."
        }
      ],
      "functions": [],
      "data_structures": [
        {
          "id": "DS-STATE-001",
          "name": "State",
          "type": "dataclass",
          "description": "Contains all information that is preserved between transactions.",
          "fields": [
            {
              "name": "_main_trie",
              "type": "Trie[Address, Optional[Account]]",
              "default": "Trie(secured=True, default=None)",
              "description": "The main account trie mapping addresses to accounts. Secured (hashed keys). Default value is None (account does not exist)."
            },
            {
              "name": "_storage_tries",
              "type": "Dict[Address, Trie[Bytes32, U256]]",
              "default": "dict()",
              "description": "Per-contract storage tries mapping storage keys to values."
            },
            {
              "name": "_snapshots",
              "type": "List[Tuple[Trie[Address, Optional[Account]], Dict[Address, Trie[Bytes32, U256]]]]",
              "default": "list()",
              "description": "Stack of snapshots for nested transaction support. Each snapshot captures the main trie and all storage tries at that point."
            },
            {
              "name": "created_accounts",
              "type": "Set[Address]",
              "default": "set()",
              "description": "Set of accounts created in the current transaction. Used by get_storage_original() and EIP-6780 SELFDESTRUCT constraints."
            }
          ]
        },
        {
          "id": "DS-STATE-002",
          "name": "TransientStorage",
          "type": "dataclass",
          "description": "Contains all information that is preserved between message calls within a transaction. Data is discarded after the transaction completes.",
          "fields": [
            {
              "name": "_tries",
              "type": "Dict[Address, Trie[Bytes32, U256]]",
              "default": "dict()",
              "description": "Per-account transient storage tries."
            },
            {
              "name": "_snapshots",
              "type": "List[Dict[Address, Trie[Bytes32, U256]]]",
              "default": "list()",
              "description": "Stack of snapshots for nested transaction support within transient storage."
            }
          ]
        }
      ],
      "state_variables": [
        {
          "id": "SV-STATE-001",
          "name": "EMPTY_ACCOUNT",
          "type": "Account",
          "description": "Sentinel value representing an empty account (imported from fork_types). Distinct from a non-existent account (None)."
        },
        {
          "id": "SV-STATE-002",
          "name": "EMPTY_TRIE_ROOT",
          "type": "Root",
          "description": "The root hash of an empty trie (imported from trie module)."
        }
      ],
      "pre_conditions": [],
      "post_conditions": [],
      "state_transitions": []
    },
    {
      "id": "SG-STATE-LIFECYCLE",
      "name": "State Lifecycle Management",
      "description": "Functions for managing the lifecycle of the State object, including resource cleanup.",
      "invariants": [],
      "functions": [
        {
          "id": "FN-LIFECYCLE-001",
          "name": "close_state",
          "signature": "close_state(state: State) -> None",
          "description": "Free resources held by the state. Used by optimized implementations to release file descriptors. Deletes the main trie, storage tries, snapshots, and created_accounts set.",
          "parameters": [
            {
              "name": "state",
              "type": "State",
              "description": "The state to close."
            }
          ],
          "returns": "None",
          "pre_conditions": [],
          "post_conditions": [
            {
              "id": "POST-LIFECYCLE-001",
              "text": "All internal trie data structures (_main_trie, _storage_tries, _snapshots, created_accounts) are deleted from the state object."
            }
          ]
        }
      ],
      "data_structures": [],
      "state_variables": [],
      "state_transitions": [
        {
          "id": "ST-LIFECYCLE-001",
          "description": "close_state: State with allocated tries -> State with all trie references removed"
        }
      ]
    },
    {
      "id": "SG-TRANSACTION-MANAGEMENT",
      "name": "Transaction Management (Snapshot/Rollback)",
      "description": "Functions for managing nested state transactions using a snapshot stack. Transactions are entirely implicit and support nesting. The state root cannot be calculated during a transaction (while snapshots exist).",
      "invariants": [
        {
          "id": "INV-TX-001",
          "text": "Transactions are entirely implicit and can be nested via the snapshots stack."
        },
        {
          "id": "INV-TX-002",
          "text": "It is not possible to calculate the state root during a transaction (assert not state._snapshots in state_root/storage_root)."
        },
        {
          "id": "INV-TX-003",
          "text": "The created_accounts set is cleared when the outermost transaction is committed or rolled back (when snapshots become empty)."
        },
        {
          "id": "INV-TX-004",
          "text": "Each begin_transaction must be matched by exactly one commit_transaction or rollback_transaction."
        },
        {
          "id": "INV-TX-005",
          "text": "Transient storage snapshots are managed in parallel with state snapshots during begin/commit/rollback."
        }
      ],
      "functions": [
        {
          "id": "FN-TX-001",
          "name": "begin_transaction",
          "signature": "begin_transaction(state: State, transient_storage: TransientStorage) -> None",
          "description": "Start a state transaction by taking a deep copy snapshot of the main trie and all storage tries, as well as all transient storage tries. The snapshots are pushed onto their respective snapshot stacks.",
          "parameters": [
            {
              "name": "state",
              "type": "State",
              "description": "The state."
            },
            {
              "name": "transient_storage",
              "type": "TransientStorage",
              "description": "The transient storage of the transaction."
            }
          ],
          "returns": "None",
          "pre_conditions": [],
          "post_conditions": [
            {
              "id": "POST-TX-001",
              "text": "A snapshot tuple (copy of _main_trie, copy of all _storage_tries) is appended to state._snapshots."
            },
            {
              "id": "POST-TX-002",
              "text": "A snapshot dict (copy of all transient_storage._tries) is appended to transient_storage._snapshots."
            }
          ]
        },
        {
          "id": "FN-TX-002",
          "name": "commit_transaction",
          "signature": "commit_transaction(state: State, transient_storage: TransientStorage) -> None",
          "description": "Commit a state transaction by discarding the most recent snapshot (popping it from the stack). If this was the outermost transaction (snapshots now empty), the created_accounts set is cleared.",
          "parameters": [
            {
              "name": "state",
              "type": "State",
              "description": "The state."
            },
            {
              "name": "transient_storage",
              "type": "TransientStorage",
              "description": "The transient storage of the transaction."
            }
          ],
          "returns": "None",
          "pre_conditions": [
            {
              "id": "PRE-TX-001",
              "text": "state._snapshots must not be empty (a transaction must have been begun)."
            }
          ],
          "post_conditions": [
            {
              "id": "POST-TX-003",
              "text": "The most recent snapshot is removed from state._snapshots."
            },
            {
              "id": "POST-TX-004",
              "text": "If state._snapshots is now empty, state.created_accounts is cleared."
            },
            {
              "id": "POST-TX-005",
              "text": "The most recent transient storage snapshot is removed from transient_storage._snapshots."
            }
          ]
        },
        {
          "id": "FN-TX-003",
          "name": "rollback_transaction",
          "signature": "rollback_transaction(state: State, transient_storage: TransientStorage) -> None",
          "description": "Rollback a state transaction, resetting the state to the point when the corresponding begin_transaction() call was made. Restores the main trie and storage tries from the popped snapshot. Restores transient storage tries from their snapshot.",
          "parameters": [
            {
              "name": "state",
              "type": "State",
              "description": "The state."
            },
            {
              "name": "transient_storage",
              "type": "TransientStorage",
              "description": "The transient storage of the transaction."
            }
          ],
          "returns": "None",
          "pre_conditions": [
            {
              "id": "PRE-TX-002",
              "text": "state._snapshots must not be empty (a transaction must have been begun)."
            }
          ],
          "post_conditions": [
            {
              "id": "POST-TX-006",
              "text": "state._main_trie and state._storage_tries are restored from the popped snapshot."
            },
            {
              "id": "POST-TX-007",
              "text": "If state._snapshots is now empty, state.created_accounts is cleared."
            },
            {
              "id": "POST-TX-008",
              "text": "transient_storage._tries is restored from the popped transient storage snapshot."
            }
          ]
        }
      ],
      "data_structures": [],
      "state_variables": [],
      "state_transitions": [
        {
          "id": "ST-TX-001",
          "description": "begin_transaction: Pushes a deep copy of (main_trie, storage_tries) onto state._snapshots and a deep copy of transient tries onto transient_storage._snapshots."
        },
        {
          "id": "ST-TX-002",
          "description": "commit_transaction: Pops the top snapshot from both stacks, keeping current state as-is. Clears created_accounts if outermost."
        },
        {
          "id": "ST-TX-003",
          "description": "rollback_transaction: Pops the top snapshot from both stacks and replaces current tries with the snapshot values. Clears created_accounts if outermost."
        }
      ]
    },
    {
      "id": "SG-ACCOUNT-CRUD",
      "name": "Account CRUD Operations",
      "description": "Functions for creating, reading, updating, and deleting accounts in the state trie. Includes both the standard get (returning EMPTY_ACCOUNT for missing) and the optional variant (returning None for missing).",
      "invariants": [
        {
          "id": "INV-ACCT-001",
          "text": "get_account() always returns a valid Account object (never None). For non-existent accounts, it returns EMPTY_ACCOUNT."
        },
        {
          "id": "INV-ACCT-002",
          "text": "get_account_optional() returns None for non-existent accounts, preserving the distinction between non-existent and empty."
        },
        {
          "id": "INV-ACCT-003",
          "text": "Setting an account to None via set_account removes the account from the trie but does NOT remove its storage. Use destroy_account to remove both."
        }
      ],
      "functions": [
        {
          "id": "FN-ACCT-001",
          "name": "get_account",
          "signature": "get_account(state: State, address: Address) -> Account",
          "description": "Get the Account object at an address. Returns EMPTY_ACCOUNT if there is no account at the address.",
          "parameters": [
            {"name": "state", "type": "State", "description": "The state."},
            {"name": "address", "type": "Address", "description": "Address to lookup."}
          ],
          "returns": "Account",
          "pre_conditions": [],
          "post_conditions": [
            {
              "id": "POST-ACCT-001",
              "text": "Return value is always a valid Account instance (never None)."
            }
          ]
        },
        {
          "id": "FN-ACCT-002",
          "name": "get_account_optional",
          "signature": "get_account_optional(state: State, address: Address) -> Optional[Account]",
          "description": "Get the Account object at an address. Returns None (rather than EMPTY_ACCOUNT) if there is no account at the address.",
          "parameters": [
            {"name": "state", "type": "State", "description": "The state."},
            {"name": "address", "type": "Address", "description": "Address to lookup."}
          ],
          "returns": "Optional[Account]",
          "pre_conditions": [],
          "post_conditions": []
        },
        {
          "id": "FN-ACCT-003",
          "name": "set_account",
          "signature": "set_account(state: State, address: Address, account: Optional[Account]) -> None",
          "description": "Set the Account object at an address. Setting to None deletes the account (but not its storage).",
          "parameters": [
            {"name": "state", "type": "State", "description": "The state."},
            {"name": "address", "type": "Address", "description": "Address to set."},
            {"name": "account", "type": "Optional[Account]", "description": "Account to set, or None to delete."}
          ],
          "returns": "None",
          "pre_conditions": [],
          "post_conditions": [
            {
              "id": "POST-ACCT-002",
              "text": "The account at the given address in the main trie is set to the provided value (or removed if None)."
            }
          ]
        },
        {
          "id": "FN-ACCT-004",
          "name": "destroy_account",
          "signature": "destroy_account(state: State, address: Address) -> None",
          "description": "Completely remove the account at the address and all of its storage. Made available exclusively for the SELFDESTRUCT opcode. Expected to be removed in a future hardfork when SELFDESTRUCT is disabled.",
          "parameters": [
            {"name": "state", "type": "State", "description": "The state."},
            {"name": "address", "type": "Address", "description": "Address of account to destroy."}
          ],
          "returns": "None",
          "pre_conditions": [],
          "post_conditions": [
            {
              "id": "POST-ACCT-003",
              "text": "The storage trie for the address is deleted (via destroy_storage)."
            },
            {
              "id": "POST-ACCT-004",
              "text": "The account at the address is set to None in the main trie (via set_account)."
            }
          ]
        },
        {
          "id": "FN-ACCT-005",
          "name": "destroy_storage",
          "signature": "destroy_storage(state: State, address: Address) -> None",
          "description": "Completely remove the storage at an address by deleting the storage trie entry.",
          "parameters": [
            {"name": "state", "type": "State", "description": "The state."},
            {"name": "address", "type": "Address", "description": "Address of account whose storage is to be deleted."}
          ],
          "returns": "None",
          "pre_conditions": [],
          "post_conditions": [
            {
              "id": "POST-ACCT-005",
              "text": "If the address had a storage trie entry, it is removed from state._storage_tries."
            }
          ]
        },
        {
          "id": "FN-ACCT-006",
          "name": "mark_account_created",
          "signature": "mark_account_created(state: State, address: Address) -> None",
          "description": "Mark an account as having been created in the current transaction. Used by get_storage_original() for an obscure edge case, and to respect EIP-6780 SELFDESTRUCT constraints. The marker is not removed even if the account creation reverts.",
          "parameters": [
            {"name": "state", "type": "State", "description": "The state."},
            {"name": "address", "type": "Address", "description": "Address of the account that has been created."}
          ],
          "returns": "None",
          "pre_conditions": [],
          "post_conditions": [
            {
              "id": "POST-ACCT-006",
              "text": "The address is added to state.created_accounts."
            },
            {
              "id": "POST-ACCT-007",
              "text": "The marker persists even if the account creation reverts (not removed by rollback)."
            }
          ]
        }
      ],
      "data_structures": [],
      "state_variables": [],
      "state_transitions": [
        {
          "id": "ST-ACCT-001",
          "description": "set_account(addr, account): Updates state._main_trie[addr] = account"
        },
        {
          "id": "ST-ACCT-002",
          "description": "set_account(addr, None): Removes addr from state._main_trie"
        },
        {
          "id": "ST-ACCT-003",
          "description": "destroy_account(addr): Removes addr from both state._storage_tries and state._main_trie"
        },
        {
          "id": "ST-ACCT-004",
          "description": "destroy_storage(addr): Removes addr from state._storage_tries only"
        },
        {
          "id": "ST-ACCT-005",
          "description": "mark_account_created(addr): Adds addr to state.created_accounts"
        }
      ]
    },
    {
      "id": "SG-STORAGE-OPERATIONS",
      "name": "Storage Operations",
      "description": "Functions for reading and writing contract storage slots. Each account can have a storage trie that maps Bytes32 keys to U256 values. Includes both current storage access and original (pre-transaction) storage access for SSTORE gas calculations.",
      "invariants": [
        {
          "id": "INV-STOR-001",
          "text": "Storage keys that have not been set return U256(0) as the default value."
        },
        {
          "id": "INV-STOR-002",
          "text": "Setting a storage value to the trie's default effectively deletes it. When all keys are deleted, the storage trie entry is removed from _storage_tries."
        },
        {
          "id": "INV-STOR-003",
          "text": "set_storage requires that the account exists in the main trie (assert trie_get(state._main_trie, address) is not None)."
        },
        {
          "id": "INV-STOR-004",
          "text": "For newly created accounts (in state.created_accounts), get_storage_original returns U256(0) regardless of any preexisting storage, because preexisting storage is ignored in the transaction where an account is created."
        }
      ],
      "functions": [
        {
          "id": "FN-STOR-001",
          "name": "get_storage",
          "signature": "get_storage(state: State, address: Address, key: Bytes32) -> U256",
          "description": "Get a value at a storage key on an account. Returns U256(0) if the storage key has not been set previously.",
          "parameters": [
            {"name": "state", "type": "State", "description": "The state."},
            {"name": "address", "type": "Address", "description": "Address of the account."},
            {"name": "key", "type": "Bytes32", "description": "Key to lookup."}
          ],
          "returns": "U256",
          "pre_conditions": [],
          "post_conditions": [
            {
              "id": "POST-STOR-001",
              "text": "Return value is always a U256 instance (asserted)."
            }
          ]
        },
        {
          "id": "FN-STOR-002",
          "name": "set_storage",
          "signature": "set_storage(state: State, address: Address, key: Bytes32, value: U256) -> None",
          "description": "Set a value at a storage key on an account. Setting to U256(0) deletes the key. If the storage trie becomes empty after the operation, it is removed from _storage_tries.",
          "parameters": [
            {"name": "state", "type": "State", "description": "The state."},
            {"name": "address", "type": "Address", "description": "Address of the account."},
            {"name": "key", "type": "Bytes32", "description": "Key to set."},
            {"name": "value", "type": "U256", "description": "Value to set at the key."}
          ],
          "returns": "None",
          "pre_conditions": [
            {
              "id": "PRE-STOR-001",
              "text": "The account must exist in the main trie (trie_get(state._main_trie, address) is not None)."
            }
          ],
          "post_conditions": [
            {
              "id": "POST-STOR-002",
              "text": "The storage trie for the address is created if it does not exist (Trie(secured=True, default=U256(0)))."
            },
            {
              "id": "POST-STOR-003",
              "text": "The key-value pair is set in the storage trie."
            },
            {
              "id": "POST-STOR-004",
              "text": "If the storage trie data becomes empty after the set, the address entry is removed from _storage_tries."
            }
          ]
        },
        {
          "id": "FN-STOR-003",
          "name": "get_storage_original",
          "signature": "get_storage_original(state: State, address: Address, key: Bytes32) -> U256",
          "description": "Get the original value in a storage slot, i.e., the value before the current transaction began. Reads from the first (outermost) snapshot. For accounts created in the current transaction, always returns U256(0).",
          "parameters": [
            {"name": "state", "type": "State", "description": "The current state."},
            {"name": "address", "type": "Address", "description": "Address of the account."},
            {"name": "key", "type": "Bytes32", "description": "Key of the storage slot."}
          ],
          "returns": "U256",
          "pre_conditions": [
            {
              "id": "PRE-STOR-002",
              "text": "state._snapshots must not be empty (must be within a transaction to have an original value)."
            }
          ],
          "post_conditions": [
            {
              "id": "POST-STOR-005",
              "text": "Return value is always a U256 instance (asserted)."
            },
            {
              "id": "POST-STOR-006",
              "text": "If address is in state.created_accounts, returns U256(0)."
            },
            {
              "id": "POST-STOR-007",
              "text": "Otherwise, returns the value from the outermost snapshot (state._snapshots[0])."
            }
          ]
        }
      ],
      "data_structures": [],
      "state_variables": [],
      "state_transitions": [
        {
          "id": "ST-STOR-001",
          "description": "set_storage(addr, key, value): Creates or updates state._storage_tries[addr][key] = value. Removes trie if empty."
        }
      ]
    },
    {
      "id": "SG-STATE-ROOT-COMPUTATION",
      "name": "State and Storage Root Computation",
      "description": "Functions for computing Merkle-Patricia trie roots of the state and individual account storage. These functions can only be called outside of transactions (when no snapshots exist).",
      "invariants": [
        {
          "id": "INV-ROOT-001",
          "text": "state_root() and storage_root() can only be called when state._snapshots is empty (no active transaction). This is enforced via assertion."
        },
        {
          "id": "INV-ROOT-002",
          "text": "An account with no storage trie entry has a storage root equal to EMPTY_TRIE_ROOT."
        }
      ],
      "functions": [
        {
          "id": "FN-ROOT-001",
          "name": "storage_root",
          "signature": "storage_root(state: State, address: Address) -> Root",
          "description": "Calculate the storage root of an account. Returns EMPTY_TRIE_ROOT if the account has no storage trie.",
          "parameters": [
            {"name": "state", "type": "State", "description": "The state."},
            {"name": "address", "type": "Address", "description": "Address of the account."}
          ],
          "returns": "Root",
          "pre_conditions": [
            {
              "id": "PRE-ROOT-001",
              "text": "state._snapshots must be empty (not in a transaction)."
            }
          ],
          "post_conditions": [
            {
              "id": "POST-ROOT-001",
              "text": "Returns the Merkle root of the account's storage trie, or EMPTY_TRIE_ROOT if no storage exists."
            }
          ]
        },
        {
          "id": "FN-ROOT-002",
          "name": "state_root",
          "signature": "state_root(state: State) -> Root",
          "description": "Calculate the state root. Uses a closure to compute each account's storage root during trie root computation.",
          "parameters": [
            {"name": "state", "type": "State", "description": "The current state."}
          ],
          "returns": "Root",
          "pre_conditions": [
            {
              "id": "PRE-ROOT-002",
              "text": "state._snapshots must be empty (not in a transaction)."
            }
          ],
          "post_conditions": [
            {
              "id": "POST-ROOT-002",
              "text": "Returns the Merkle root of the entire state trie, with each account's storage root computed via storage_root()."
            }
          ]
        }
      ],
      "data_structures": [],
      "state_variables": [],
      "state_transitions": []
    },
    {
      "id": "SG-ACCOUNT-PREDICATES",
      "name": "Account Query Predicates",
      "description": "Boolean query functions for checking various properties of accounts in the state trie. These are pure reads with no side effects.",
      "invariants": [
        {
          "id": "INV-PRED-001",
          "text": "account_exists checks for non-None (any Account object including EMPTY_ACCOUNT means the account exists)."
        },
        {
          "id": "INV-PRED-002",
          "text": "is_account_alive requires both existence (not None) AND non-emptiness (not equal to EMPTY_ACCOUNT)."
        }
      ],
      "functions": [
        {
          "id": "FN-PRED-001",
          "name": "account_exists",
          "signature": "account_exists(state: State, address: Address) -> bool",
          "description": "Checks if an account exists in the state trie. Returns True if the account is present (even if it is EMPTY_ACCOUNT).",
          "parameters": [
            {"name": "state", "type": "State", "description": "The state."},
            {"name": "address", "type": "Address", "description": "Address of the account."}
