    {
      "id": "SG-TX-ENCODING",
      "name": "Transaction Encoding and Decoding",
      "description": "Handles serialization (encoding) and deserialization (decoding) of transactions. Legacy transactions use raw RLP encoding, while typed transactions (EIP-2718) use a type-byte prefix followed by RLP encoding. Type identifiers: 0x01=AccessList, 0x02=FeeMarket, 0x03=Blob, 0x04=SetCode.",
      "invariants": [
        {
          "id": "INV-ENC-001",
          "text": "encode_transaction and decode_transaction are inverse operations: decode_transaction(encode_transaction(tx)) must yield a transaction equivalent to tx for all valid transactions."
        },
        {
          "id": "INV-ENC-002",
          "text": "Transaction type byte prefixes are unique and ordered: 0x01 (AccessList), 0x02 (FeeMarket), 0x03 (Blob), 0x04 (SetCode). Legacy transactions have no prefix."
        },
        {
          "id": "INV-ENC-003",
          "text": "Legacy transactions are returned as-is (not re-encoded) by encode_transaction, preserving the original RLP-serializable object."
        }
      ],
