          "id": "FN-ENC-001",
          "name": "encode_transaction",
          "signature": "encode_transaction(tx: Transaction) -> LegacyTransaction | Bytes",
          "description": "Encode a transaction into its RLP or typed transaction format. Legacy transactions are returned as-is, while other transaction types are prefixed with their type identifier and RLP encoded.",
          "parameters": [
            {"name": "tx", "type": "Transaction", "description": "The transaction to encode."}
          ],
          "returns": {
            "type": "LegacyTransaction | Bytes",
            "description": "The encoded transaction -- either the original LegacyTransaction object or typed-transaction bytes."
          },
          "preconditions": [
            "tx must be one of the five recognized transaction types."
          ],
          "postconditions": [
            "If tx is LegacyTransaction, returns tx unchanged.",
            "If tx is a typed transaction, returns bytes starting with the appropriate type prefix (0x01-0x04) followed by RLP encoding."
          ],
          "error_conditions": [
            "Raises Exception if tx is not a recognized transaction type."
          ],
          "state_transitions": []
        },
        {
          "id": "FN-ENC-002",
          "name": "decode_transaction",
          "signature": "decode_transaction(tx: LegacyTransaction | Bytes) -> Transaction",
          "description": "Decode a transaction from its RLP or typed transaction format. Legacy transactions are returned as-is, while other transaction types are decoded based on their type identifier prefix.",
          "parameters": [
            {"name": "tx", "type": "LegacyTransaction | Bytes", "description": "The encoded transaction to decode."}
          ],
          "returns": {
            "type": "Transaction",
            "description": "The decoded transaction object."
          },
          "preconditions": [
            "If tx is Bytes, the first byte must be a valid type identifier (1, 2, 3, or 4)."
          ],
          "postconditions": [
            "Returns a fully-populated transaction dataclass of the correct type.",
            "If tx is LegacyTransaction, returns tx unchanged."
          ],
          "error_conditions": [
            "Raises TransactionTypeError if the type byte is not recognized (not 1-4)."
          ],
          "state_transitions": []
        }
      ],
      "data_structures": []
    },
    {
      "id": "SG-TX-VALIDATION",
      "name": "Transaction Validation",
      "description": "Validates transactions before execution by checking gas sufficiency, nonce bounds, init code size limits, and per-transaction gas limits. Implements the EIP-7623 calldata floor gas cost mechanism. Returns both intrinsic gas cost and calldata floor gas cost.",
      "invariants": [
        {
          "id": "INV-VAL-001",
          "text": "The effective gas requirement for a transaction is max(intrinsic_gas, calldata_floor_gas_cost), and it must not exceed the transaction's gas limit."
        },
        {
          "id": "INV-VAL-002",
          "text": "Transaction nonce must be strictly less than U64.MAX_VALUE (2^64 - 1), as per EIP-2681."
        },
        {
          "id": "INV-VAL-003",
          "text": "Contract creation transactions (to == Bytes0) must have data length not exceeding MAX_INIT_CODE_SIZE."
        },
        {
          "id": "INV-VAL-004",
          "text": "Transaction gas limit must not exceed TX_MAX_GAS_LIMIT (16,777,216)."
        }
      ],
      "state_variables": [],
      "functions": [
        {
          "id": "FN-VAL-001",
          "name": "validate_transaction",
          "signature": "validate_transaction(tx: Transaction) -> Tuple[Uint, Uint]",
          "description": "Verifies a transaction. The gas in a transaction gets used to pay for the intrinsic cost of operations, therefore if there is insufficient gas then it would not be possible to execute a transaction and it will be declared invalid. Additionally, the nonce of a transaction must not equal or exceed the limit defined in EIP-2681. Also, the code size of a contract creation transaction must be within limits of the protocol. Returns the intrinsic gas cost and the minimum calldata gas cost.",
          "parameters": [
            {"name": "tx", "type": "Transaction", "description": "The transaction to validate."}
          ],
          "returns": {
            "type": "Tuple[Uint, Uint]",
            "description": "A tuple of (intrinsic_gas_cost, calldata_floor_gas_cost)."
          },
          "preconditions": [
            "tx must be a valid Transaction variant with all fields populated."
          ],
          "postconditions": [
            "max(intrinsic_gas, calldata_floor_gas_cost) <= tx.gas.",
            "U256(tx.nonce) < U256(U64.MAX_VALUE).",
            "If tx.to == Bytes0, len(tx.data) <= MAX_INIT_CODE_SIZE.",
            "tx.gas <= TX_MAX_GAS_LIMIT."
          ],
          "error_conditions": [
            "Raises InsufficientTransactionGasError if max(intrinsic_gas, calldata_floor_gas_cost) > tx.gas.",
            "Raises NonceOverflowError if U256(tx.nonce) >= U256(U64.MAX_VALUE).",
            "Raises InitCodeTooLargeError if contract creation with data exceeding MAX_INIT_CODE_SIZE.",
            "Raises TransactionGasLimitExceededError if tx.gas > TX_MAX_GAS_LIMIT."
          ],
          "state_transitions": []
        },
        {
          "id": "FN-VAL-002",
          "name": "calculate_intrinsic_cost",
          "signature": "calculate_intrinsic_cost(tx: Transaction) -> Tuple[Uint, Uint]",
          "description": "Calculates the gas that is charged before execution is started. The intrinsic cost includes: (1) Base cost (TX_BASE_COST), (2) Cost for data (zero and non-zero bytes via calldata token formula), (3) Cost for contract creation (if applicable), (4) Cost for access list entries (if applicable), (5) Cost for authorizations (if applicable, EIP-7702). Returns the intrinsic gas cost and the minimum calldata gas cost.",
          "parameters": [
            {"name": "tx", "type": "Transaction", "description": "The transaction to calculate intrinsic cost for."}
          ],
          "returns": {
            "type": "Tuple[Uint, Uint]",
            "description": "A tuple of (intrinsic_gas_cost, calldata_floor_gas_cost)."
          },
          "preconditions": [],
          "postconditions": [
            "intrinsic_gas_cost >= TX_BASE_COST (21000).",
            "calldata_floor_gas_cost = tokens_in_calldata * FLOOR_CALLDATA_COST + TX_BASE_COST.",
            "tokens_in_calldata = zero_bytes + (total_bytes - zero_bytes) * 4.",
            "intrinsic_gas_cost = TX_BASE_COST + data_cost + create_cost + access_list_cost + auth_cost."
          ],
          "error_conditions": [],
          "state_transitions": [],
          "computation_details": {
            "calldata_token_formula": "tokens_in_calldata = zero_bytes + (len(tx.data) - zero_bytes) * 4",
            "calldata_floor": "calldata_floor_gas_cost = tokens_in_calldata * FLOOR_CALLDATA_COST + TX_BASE_COST",
            "data_cost": "data_cost = tokens_in_calldata * STANDARD_CALLDATA_TOKEN_COST",
            "create_cost": "TX_CREATE_COST + init_code_cost(len(tx.data)) if contract creation, else 0",
            "access_list_cost": "sum of TX_ACCESS_LIST_ADDRESS_COST per address + TX_ACCESS_LIST_STORAGE_KEY_COST per slot",
            "auth_cost": "PER_EMPTY_ACCOUNT_COST * len(tx.authorizations) for SetCodeTransaction only",
            "total_intrinsic": "TX_BASE_COST + data_cost + create_cost + access_list_cost + auth_cost"
          }
        }
      ],
      "data_structures": []
    },
    {
      "id": "SG-TX-SIGNATURE",
      "name": "Transaction Signature Recovery",
      "description": "Recovers the sender address from a transaction's ECDSA signature components (v/y_parity, r, s). Each transaction type has its own signing hash computation method. Uses the secp256k1 elliptic curve for signature recovery and keccak256 for hashing.",
      "invariants": [
        {
          "id": "INV-SIG-001",
          "text": "The r value must be in the range (0, SECP256K1N) -- strictly greater than 0 and strictly less than the secp256k1 curve order."
        },
        {
          "id": "INV-SIG-002",
          "text": "The s value must be in the range (0, SECP256K1N / 2] -- strictly greater than 0 and at most half of the curve order (low-s normalization)."
        },
        {
          "id": "INV-SIG-003",
          "text": "For typed transactions (EIP-2930, EIP-1559, EIP-4844, EIP-7702), y_parity must be exactly 0 or 1."
        },
        {
          "id": "INV-SIG-004",
          "text": "For legacy transactions, v must be either 27/28 (pre-EIP-155) or 35+chain_id*2 / 36+chain_id*2 (EIP-155)."
        },
        {
          "id": "INV-SIG-005",
          "text": "The sender address is derived deterministically from the signature and signing hash: Address = keccak256(recovered_public_key)[12:32]."
        }
      ],
      "state_variables": [],
      "functions": [
        {
          "id": "FN-SIG-001",
          "name": "recover_sender",
          "signature": "recover_sender(chain_id: U64, tx: Transaction) -> Address",
          "description": "Extracts the sender address from a transaction. The v, r, and s values are the three parts that make up the signature of a transaction. In order to recover the sender of a transaction the two components needed are the signature (v, r, s) and the signing hash.",
          "parameters": [
            {"name": "chain_id", "type": "U64", "description": "The chain identifier for replay protection."},
            {"name": "tx", "type": "Transaction", "description": "The transaction from which to recover the sender."}
          ],
          "returns": {
            "type": "Address",
            "description": "The 20-byte Ethereum address of the transaction sender."
          },
          "preconditions": [
            "0 < r < SECP256K1N.",
            "0 < s <= SECP256K1N / 2.",
            "Signature parity/v values must be valid for the transaction type."
          ],
          "postconditions": [
            "Returns a valid 20-byte Address derived from keccak256(public_key)[12:32]."
          ],
          "error_conditions": [
            "Raises InvalidSignatureError('bad r') if r is out of range.",
            "Raises InvalidSignatureError('bad s') if s is out of range.",
            "Raises InvalidSignatureError('bad v') if legacy v value does not match expected patterns.",
            "Raises InvalidSignatureError('bad y_parity') if typed transaction y_parity is not 0 or 1."
          ],
          "state_transitions": [],
          "dispatch_table": {
            "LegacyTransaction (pre-155)": "signing_hash_pre155(tx) when v in {27, 28}",
            "LegacyTransaction (EIP-155)": "signing_hash_155(tx, chain_id) when v in {35+chain_id*2, 36+chain_id*2}",
            "AccessListTransaction": "signing_hash_2930(tx)",
            "FeeMarketTransaction": "signing_hash_1559(tx)",
            "BlobTransaction": "signing_hash_4844(tx)",
            "SetCodeTransaction": "signing_hash_7702(tx)"
          }
        },
        {
          "id": "FN-SIG-002",
          "name": "signing_hash_pre155",
          "signature": "signing_hash_pre155(tx: LegacyTransaction) -> Hash32",
          "description": "Compute the hash of a transaction used in a legacy (pre EIP-155) signature.",
          "parameters": [
            {"name": "tx", "type": "LegacyTransaction", "description": "The legacy transaction."}
          ],
          "returns": {
            "type": "Hash32",
            "description": "keccak256 hash of RLP-encoded (nonce, gas_price, gas, to, value, data)."
          },
          "preconditions": [],
          "postconditions": [],
          "error_conditions": [],
          "rlp_fields": ["tx.nonce", "tx.gas_price", "tx.gas", "tx.to", "tx.value", "tx.data"]
        },
        {
