          "name": "signing_hash_155",
          "signature": "signing_hash_155(tx: LegacyTransaction, chain_id: U64) -> Hash32",
          "description": "Compute the hash of a transaction used in an EIP-155 signature.",
          "parameters": [
            {"name": "tx", "type": "LegacyTransaction", "description": "The legacy transaction."},
            {"name": "chain_id", "type": "U64", "description": "The chain identifier."}
          ],
          "returns": {
            "type": "Hash32",
