          },
          "preconditions": [],
          "postconditions": [],
          "error_conditions": [],
          "eip_reference": "EIP-155",
          "rlp_fields": ["tx.nonce", "tx.gas_price", "tx.gas", "tx.to", "tx.value", "tx.data", "chain_id", "0", "0"]
        },
        {
          "id": "FN-SIG-004",
          "name": "signing_hash_2930",
          "signature": "signing_hash_2930(tx: AccessListTransaction) -> Hash32",
          "description": "Compute the hash of a transaction used in an EIP-2930 signature.",
          "parameters": [
