        },
        {
          "id": "FN-SIG-005",
          "name": "signing_hash_1559",
          "signature": "signing_hash_1559(tx: FeeMarketTransaction) -> Hash32",
          "description": "Compute the hash of a transaction used in an EIP-1559 signature.",
          "parameters": [
            {"name": "tx", "type": "FeeMarketTransaction", "description": "The fee market transaction."}
          ],
          "returns": {
