        "id": "SG-STATE-DATA-STRUCTURES",
        "name": "State Data Structures",
        "description": "Core data structures that hold all information preserved between transactions. The State contains a main account trie and per-contract storage tries. TransientStorage holds data preserved only within a single transaction across message calls.",
        "invariants": [
          {"id": "INV-STATE-001", "text": "There is a distinction between an account that does not exist (None) and EMPTY_ACCOUNT. A non-existent account maps to None in the trie, while EMPTY_ACCOUNT is a valid Account object with zero values."},
          {"id": "INV-STATE-002", "text": "The main trie is a secured trie (hashed keys) with a default value of None for non-existent accounts."},
          {"id": "INV-STATE-003", "text": "Each storage trie is a secured trie with a default value of U256(0)."},
          {"id": "INV-STATE-004", "text": "TransientStorage is scoped to a single transaction and is not preserved across transactions."}
        ],
        "functions": [],
        "data_structures": [
          {
            "id": "DS-STATE-001",
            "name": "State",
            "type": "dataclass",
            "description": "Contains all information that is preserved between transactions.",
            "fields": [
              {"name": "_main_trie", "type": "Trie[Address, Optional[Account]]", "default": "Trie(secured=True, default=None)", "description": "The main account trie mapping addresses to accounts."},
              {"name": "_storage_tries", "type": "Dict[Address, Trie[Bytes32, U256]]", "default": "dict()", "description": "Per-contract storage tries mapping storage keys to values."},
