            ]
          },
          {
            "id": "DS-STATE-002",
            "name": "TransientStorage",
            "type": "dataclass",
            "description": "Contains all information that is preserved between message calls within a transaction.",
            "fields": [
              {"name": "_tries", "type": "Dict[Address, Trie[Bytes32, U256]]", "default": "dict()", "description": "Per-account transient storage tries."},
              {"name": "_snapshots", "type": "List[Dict[Address, Trie[Bytes32, U256]]]", "default": "list()", "description": "Stack of snapshots for nested transaction support within transient storage."}
            ]
          }
        ],
        "state_variables": [
          {"id": "SV-STATE-001", "name": "EMPTY_ACCOUNT", "type": "Account", "description": "Sentinel value representing an empty account. Distinct from a non-existent account (None)."},
          {"id": "SV-STATE-002", "name": "EMPTY_TRIE_ROOT", "type": "Root", "description": "The root hash of an empty trie."}
