      },
      {
        "id": "SG-TRANSACTION-MANAGEMENT",
        "name": "Transaction Management (Snapshot/Rollback)",
        "description": "Functions for managing nested state transactions using a snapshot stack. The state root cannot be calculated during a transaction.",
        "invariants": [
          {"id": "INV-TX-001", "text": "Transactions are entirely implicit and can be nested via the snapshots stack."},
          {"id": "INV-TX-002", "text": "It is not possible to calculate the state root during a transaction (assert not state._snapshots in state_root/storage_root)."},
          {"id": "INV-TX-003", "text": "The created_accounts set is cleared when the outermost transaction is committed or rolled back."},
          {"id": "INV-TX-004", "text": "Each begin_transaction must be matched by exactly one commit_transaction or rollback_transaction."},
          {"id": "INV-TX-005", "text": "Transient storage snapshots are managed in parallel with state snapshots during begin/commit/rollback."}
        ],
        "functions": [
          {
            "id": "FN-TX-001",
